import clsx from 'clsx';
import { useCallback, useEffect, useState } from 'react';
import { FormProvider, SubmitHandler, useForm } from 'react-hook-form';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { useSetOnBack } from '~/widgets/sub-layout/use-sub-layout';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { useStplatReadListQuery } from '~/entities/pin/api/use-stplat-read-list-query';
import { Term } from '~/entities/sign-up/ui/term';
import { YesOrNo } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { overlay } from '~/shared/lib/overlay';
import { PATHS } from '~/shared/routes/paths';
import { CheckBox } from '~/shared/ui/check-box';
import { Dialog } from '~/shared/ui/dialogs/dialog';

type TermsInputs = {
  agreed: string[];
};

const EMPTY_SELECT_ALL_VALUE = '__EMPTY_SELECT_ALL__';

export const TermsAndConditionsPage = () => {
  const { routerState: backState } = useGetRouterState<SuperAppEncData>();
  const { routerState: state } = useGetRouterState<SuperAppEncData>();
  const { navigate } = useNavigate();
  useSetOnBack(() => navigate(PATHS.account.verifyBank, { replace: true, state: { ...backState } }));
  const form = useForm<TermsInputs>();
  const { register, handleSubmit, watch } = form;
  const watchAllFields = watch('agreed', []);
  const [disabled, setDisabled] = useState(false);
  const { data: list } = useStplatReadListQuery();
  const selectAllValue =
    list && list.length > 0 ? list.map((item) => item.stplatManageId) : list ? [EMPTY_SELECT_ALL_VALUE] : [];

  const fnTermView = useCallback(
    (index: number) => {
      if (list) {
        overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
          return (
            <Dialog
              afterLeave={unmount}
              open={isOpen}
              onClose={close}
              message={<Term contents={list[index]?.stplatCn ?? ''} />}
              buttonLabel={[]}
              fullScreenMode
            />
          );
        });
      }
    },
    [list],
  );

  const onSubmit: SubmitHandler<TermsInputs> = () => {
    navigate(PATHS.signUp.arsNumber, {
      replace: true,
      state: { ...state, stplatYn: YesOrNo.예, etcNtcnYn: YesOrNo.예 },
    });
  };

  useEffect(() => {
    const agreedValues = Array.isArray(watchAllFields) ? watchAllFields : watchAllFields ? [watchAllFields] : [];
    if (!list) {
      setDisabled(false);
      return;
    }

    //약관이 등록되어있어야하지만 현재는 빈값일때도 모두동의 체크 가능하도록 처리 (다음으로 넘어가기 위함)
    if (list.length === 0) {
      setDisabled(agreedValues.includes(EMPTY_SELECT_ALL_VALUE));
      return;
    }

    const hasValue = list.map((item) => item.stplatManageId);
    const isAllChecked = hasValue.every((v: any) => agreedValues.includes(v)) ?? false;
    setDisabled(isAllChecked);
  }, [watchAllFields, list]);

  return (
    <div className="has-btm-btn justify-content flex flex-auto flex-col">
      <div className="sub-desc">
        <h3
          dangerouslySetInnerHTML={{
            __html: i18n.t('text:agreeToAutomaticWithdrawal'),
          }}
        ></h3>
      </div>
      <FormProvider {...form}>
        <div className="b-fixed">
          <div className="policy-list">
            <ul>
              <li className="all">
                <CheckBox
                  label={<p className="ml10">{i18n.t('agreeToAllTerms')}</p>}
                  value={selectAllValue}
                  {...register('agreed')}
                  isSelectAll
                />
              </li>
              {list && list.length > 0 ? (
                list?.map((item, index) => (
                  <li key={`${item.stplatManageId}_${index}`}>
                    <CheckBox
                      label={
                        <p>
                          <span className="req ml10">{i18n.t('required')}</span> {item.stplatNm}
                        </p>
                      }
                      value={item.stplatManageId}
                      {...register(`agreed`)}
                    />
                    <button type="button" className="btn arr-right" onClick={() => fnTermView(index)}>
                      <span>{i18n.t('viewTerms')}</span>
                    </button>
                  </li>
                ))
              ) : (
                <div>등록된 약관이 없습니다.</div>
              )}
            </ul>
          </div>
          <div className="btm-btn-area">
            <button
              type="submit"
              disabled={!disabled}
              className={clsx('btm-btn app', { disabled: !disabled })}
              onClick={handleSubmit(onSubmit)}
            >
              {i18n.t('next')}
            </button>
          </div>
        </div>
      </FormProvider>
    </div>
  );
};
